<script setup lang="ts">
import { ArrowDown, ArrowUp, ArrowUpDown, ChevronRight, Droplet } from "lucide-vue-next";
import AceiteEstadoBadge from "./AceiteEstadoBadge.vue"; import AceiteSystemsSummary from "./AceiteSystemsSummary.vue";
import { formatNumber } from "@/stores/dbequipos/engrase/catalogo/aceitesCatalogo.helpers";
import type { CatalogoAceiteItem,CatalogoAceiteSortKey,CatalogoSortDirection } from "@/stores/dbequipos/engrase/catalogo/aceitesCatalogo.types";
const props=defineProps<{items:readonly CatalogoAceiteItem[];selectedId:number|null;sortKey:CatalogoAceiteSortKey;sortDirection:CatalogoSortDirection}>();const emit=defineEmits<{select:[CatalogoAceiteItem,HTMLElement];sort:[CatalogoAceiteSortKey]}>();
function icon(key:CatalogoAceiteSortKey){return props.sortKey!==key?ArrowUpDown:props.sortDirection==="asc"?ArrowUp:ArrowDown}function aria(key:CatalogoAceiteSortKey):"ascending"|"descending"|"none"{return props.sortKey!==key?"none":props.sortDirection==="asc"?"ascending":"descending"}function select(item:CatalogoAceiteItem,event:Event){emit("select",item,event.currentTarget as HTMLElement)}
</script>
<template><div class="hidden overflow-hidden rounded-lg border border-gray-200 bg-white shadow-sm lg:block"><table class="w-full table-fixed border-collapse text-left text-xs"><thead class="h-9 bg-gray-50 text-gray-600"><tr>
  <th class="w-[25%] px-3" :aria-sort="aria('nombre')"><button class="inline-flex cursor-pointer items-center gap-1 font-semibold" @click="emit('sort','nombre')">Nombre<component :is="icon('nombre')" class="h-3.5 w-3.5" /></button></th>
  <th class="w-[25%] px-3" :aria-sort="aria('sistemas')"><button class="inline-flex cursor-pointer items-center gap-1 font-semibold" @click="emit('sort','sistemas')">Sistemas asociados<component :is="icon('sistemas')" class="h-3.5 w-3.5" /></button></th>
  <th class="w-[16%] px-3" :aria-sort="aria('estado')"><button class="inline-flex cursor-pointer items-center gap-1 font-semibold" @click="emit('sort','estado')">Estado<component :is="icon('estado')" class="h-3.5 w-3.5" /></button></th>
  <th class="px-3 font-semibold">Resumen de uso</th><th class="w-10"><span class="sr-only">Abrir</span></th></tr></thead>
  <tbody><tr v-for="item in items" :key="item.id" tabindex="0" class="h-16 cursor-pointer border-t border-gray-100 text-gray-700 outline-none transition hover:bg-main/5 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-main" :class="selectedId===item.id?'bg-main/5 shadow-[inset_3px_0_0_var(--color-main)]':''" :aria-selected="selectedId===item.id" @click="select(item,$event)" @keydown.enter.prevent="select(item,$event)" @keydown.space.prevent="select(item,$event)"><td class="px-3"><div class="flex items-center gap-2"><span class="grid h-8 w-8 shrink-0 place-items-center rounded-md bg-main/7 text-main"><Droplet class="h-4 w-4" /></span><strong class="break-words text-main">{{item.nombre}}</strong></div></td><td class="px-3"><AceiteSystemsSummary :items="item.sistemas" /></td><td class="px-3"><AceiteEstadoBadge :activo="item.activo" /></td><td class="px-3"><dl class="max-w-[220px] space-y-1 tabular-nums"><div class="flex justify-between gap-4"><dt>Equipos</dt><dd>{{formatNumber(item.impacto.totalEquipos)}}</dd></div><div class="flex justify-between gap-4"><dt>Total asignaciones</dt><dd>{{formatNumber(item.impacto.totalAsignaciones)}}</dd></div></dl></td><td><ChevronRight class="h-4 w-4 text-main" /></td></tr></tbody>
</table></div></template>
